```python
def factorial(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("n必须是整数")
    if n < 0:
        raise ValueError("n不能为负数")
    result = 1
    for value in range(2, n + 1):
        result *= value
    return result
